<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Content-Type:text/html;charset=utf-8');echo '<!doctype html><html lang="sv"><meta charset="utf-8"><title>Installera Ilinium</title><style>body{font:16px system-ui;max-width:600px;margin:60px auto;padding:20px}input,button{font:inherit;padding:12px;width:100%;box-sizing:border-box;margin:8px 0}button{background:#702c45;color:white;border:0}</style><h1>Installera Ilinium på STRATO</h1><p>Ange setup_key från api/config.php. Installationen skapar databastabeller, administratören och importerar innehållet.</p><form method="post"><input type="password" name="setup_key" required><button>Installera</button></form></html>';exit;}
$c=config();if(!hash_equals((string)$c['setup_key'],(string)($_POST['setup_key']??'')))die('Fel installationsnyckel.');
$sqlite=(config()['db_driver']??'mysql')==='sqlite';
$schema=$sqlite?'schema.sqlite.sql':'schema.sql';
foreach(array_filter(array_map('trim',preg_split('/;\s*(?:\r?\n|$)/',file_get_contents(__DIR__.'/'.$schema)))) as $sql)db()->exec($sql);
$email=strtolower(trim((string)$c['admin_email']));$pw=(string)$c['admin_password'];if(strlen($pw)<12)die('Adminlösenordet måste vara minst 12 tecken.');$userSql=$sqlite?'INSERT INTO users(id,email,password_hash) VALUES(?,?,?) ON CONFLICT(email) DO UPDATE SET password_hash=excluded.password_hash':'INSERT INTO users(id,email,password_hash) VALUES(?,?,?) ON DUPLICATE KEY UPDATE password_hash=VALUES(password_hash)';$s=db()->prepare($userSql);$s->execute([uuid(),$email,password_hash($pw,PASSWORD_DEFAULT)]);
$seedFile=__DIR__.'/seed.json';if(is_file($seedFile)){ $seed=json_decode(file_get_contents($seedFile),true); foreach($seed as $table=>$rows){if(!is_array($rows))continue;foreach($rows as $row){$cols=array_keys($row);$vals=array_map(fn($v)=>is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE):$v,array_values($row));$sql=($sqlite?'INSERT OR REPLACE':'INSERT').' INTO `'.$table.'` (`'.implode('`,`',$cols).'`) VALUES ('.implode(',',array_fill(0,count($cols),'?')).')';if(!$sqlite)$sql.=' ON DUPLICATE KEY UPDATE '.implode(',',array_map(fn($x)=>"`$x`=VALUES(`$x`)",array_filter($cols,fn($x)=>!in_array($x,['id','weekday'],true))));db()->prepare($sql)->execute($vals);}}}
echo '<h1>Installationen är klar</h1><p>Ta bort api/install.php från webbhotellet och logga sedan in via /auth.</p>';
